//! Contract emitter — radiates the contract to the committed C# binding
//! `app/FindMyFiles/Engine/Generated/EngineContract.g.cs` (ADR-0018).
//!
//! Every value is read from the compiled contract items themselves
//! (`offset_of!`/`size_of!` on the real `#[repr(C)]` types, the actual
//! consts), so the generated numbers cannot drift from the Rust truth.
//! `tests/drift.rs` runs `--check` inside the nextest workspace suite, so an
//! out-of-date generated file fails the ordinary test gate.
//!
//! Usage: `just contract-gen` (write) / `gen-contract --check` (verify).

use std::mem::{offset_of, size_of};
use std::path::PathBuf;

use fmf_contract::pod::{
    FmfBlob, FmfEvent, FmfPage, FmfQueryOptions, FmfRow, FmfVolumeStatus, FrameHeader, row_flags,
};
use fmf_contract::{codes, counters, events, limits, opcodes, options, versions};

fn pascal(snake: &str) -> String {
    snake
        .split('_')
        .map(|w| {
            let mut c = w.chars();
            match c.next() {
                Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
                None => String::new(),
            }
        })
        .collect()
}

fn render() -> String {
    let mut o = String::new();
    let mut w = |line: &str| {
        o.push_str(line);
        o.push('\n');
    };

    w("// <auto-generated>");
    w("//   Generated by fmf-contract's gen-contract from the canonical contract");
    w("//   definitions (engine/crates/fmf-contract — ADR-0018). DO NOT EDIT:");
    w("//   regenerate with `just contract-gen`; `just test` fails");
    w("//   on drift. Field offsets are the offset_of! values of the compiled");
    w("//   Rust #[repr(C)] types — no hand-derived numbers exist on this side.");
    w("// </auto-generated>");
    w("");
    w("using System.Runtime.InteropServices;");
    w("");
    w("namespace FindMyFiles.Engine;");
    w("");
    w("/// <summary>The engine contract, radiated from fmf-contract.</summary>");
    w("internal static class EngineContract");
    w("{");
    w(&format!(
        "    public const uint AbiVersion = {};",
        versions::ABI_VERSION
    ));
    w(&format!(
        "    public const uint ProtocolVersion = {};",
        versions::PROTOCOL_VERSION
    ));
    w("");
    w("    /// <summary>Pipe name without the <c>\\\\.\\pipe\\</c> prefix.</summary>");
    w(&format!(
        "    public const string PipeNameShort = \"{}\";",
        versions::PIPE_NAME_SHORT
    ));
    w("");
    w("    /// <summary>SCM service name (the in-app service setup drives it).</summary>");
    w(&format!(
        "    public const string ServiceName = \"{}\";",
        versions::SERVICE_NAME
    ));
    w("");
    w(
        "    /// <summary>Exact SCM Description required before starting an installed service.</summary>",
    );
    w(&format!(
        "    public const string ServiceProtocolMarker = \"{}\";",
        versions::SERVICE_PROTOCOL_MARKER
    ));
    w("");
    w("    /// <summary>Status codes (frame header / FFI returns). Append-only.</summary>");
    w("    public static class Status");
    w("    {");
    for (name, v) in [
        ("Ok", codes::OK),
        ("InvalidArg", codes::INVALID_ARG),
        ("Stale", codes::STALE),
        ("NotAdmin", codes::NOT_ADMIN),
        ("Volume", codes::VOLUME),
        ("QuerySyntax", codes::QUERY_SYNTAX),
        ("Io", codes::IO),
        ("Locked", codes::LOCKED),
        ("Cancelled", codes::CANCELLED),
        ("Panic", codes::PANIC),
    ] {
        w(&format!("        public const int {name} = {v};"));
    }
    w("    }");
    w("");
    w("    /// <summary>Pipe opcodes. Event pushes reuse 1..6 as the kind with");
    w("    /// the event flag set — branch on the flag before the opcode.</summary>");
    w("    public static class Op");
    w("    {");
    for (name, v) in [
        ("Hello", opcodes::HELLO),
        ("Subscribe", opcodes::SUBSCRIBE),
        ("Unsubscribe", opcodes::UNSUBSCRIBE),
        ("ListVolumes", opcodes::LIST_VOLUMES),
        ("IndexStart", opcodes::INDEX_START),
        ("IndexStatus", opcodes::INDEX_STATUS),
        ("Query", opcodes::QUERY),
        ("ResultPage", opcodes::RESULT_PAGE),
        ("ResultFree", opcodes::RESULT_FREE),
        ("Stats", opcodes::STATS),
        ("ServiceInfo", opcodes::SERVICE_INFO),
        ("QueryCancel", opcodes::QUERY_CANCEL),
    ] {
        w(&format!("        public const ushort {name} = {v};"));
    }
    w("    }");
    w("");
    w("    // ── Limits ──────────────────────────────────────────────────────");
    w(&format!(
        "    public const uint MaxPayloadLen = {};",
        limits::MAX_PAYLOAD_LEN
    ));
    w(&format!(
        "    public const int MaxResultsPerConn = {};",
        limits::MAX_RESULTS_PER_CONN
    ));
    w(&format!(
        "    public const int EventQueueCap = {};",
        limits::EVENT_QUEUE_CAP
    ));
    w(&format!(
        "    public const int PageRows = {};",
        limits::PAGE_ROWS
    ));
    w(&format!(
        "    public const int MaxPageRows = {};",
        limits::MAX_PAGE_ROWS
    ));
    w(&format!(
        "    public const int MaxVolumes = {};",
        limits::MAX_VOLUMES
    ));
    w(&format!(
        "    public const int MaxQueryBytes = {};",
        limits::MAX_QUERY_BYTES
    ));
    w(&format!(
        "    public const int MaxQueryGroups = {};",
        limits::MAX_QUERY_GROUPS
    ));
    w(&format!(
        "    public const int MaxQueryTerms = {};",
        limits::MAX_QUERY_TERMS
    ));
    w(&format!(
        "    public const int MaxRegexTerms = {};",
        limits::MAX_REGEX_TERMS
    ));
    w(&format!(
        "    public const int MaxIndexStartPayloadLen = {};",
        limits::MAX_INDEX_START_PAYLOAD_LEN
    ));
    w("");
    w("    // ── POD layouts (offset_of! truth) ──────────────────────────────");
    w(&format!(
        "    public const int FrameHeaderLen = {};",
        size_of::<FrameHeader>()
    ));
    w("    public static class FrameOffsets");
    w("    {");
    w(&format!(
        "        public const int Len = {};",
        offset_of!(FrameHeader, len)
    ));
    w(&format!(
        "        public const int Opcode = {};",
        offset_of!(FrameHeader, opcode)
    ));
    w(&format!(
        "        public const int Flags = {};",
        offset_of!(FrameHeader, flags)
    ));
    w(&format!(
        "        public const int RequestId = {};",
        offset_of!(FrameHeader, request_id)
    ));
    w(&format!(
        "        public const int Status = {};",
        offset_of!(FrameHeader, status)
    ));
    w("    }");
    w("");
    w(&format!(
        "    public const int RowSize = {};",
        size_of::<FmfRow>()
    ));
    w("    /// <summary>Canonical FmfRow.Flags values; unknown bits are reserved zero.</summary>");
    w("    public static class RowFlags");
    w("    {");
    w(&format!(
        "        public const uint Directory = {};",
        row_flags::DIRECTORY
    ));
    w(&format!(
        "        public const uint KnownMask = {};",
        row_flags::KNOWN_MASK
    ));
    w("    }");
    w("");
    w("    public static class RowOffsets");
    w("    {");
    w(&format!(
        "        public const int EntryRef = {};",
        offset_of!(FmfRow, entry_ref)
    ));
    w(&format!(
        "        public const int Frn = {};",
        offset_of!(FmfRow, frn)
    ));
    w(&format!(
        "        public const int Size = {};",
        offset_of!(FmfRow, size)
    ));
    w(&format!(
        "        public const int Mtime = {};",
        offset_of!(FmfRow, mtime)
    ));
    w(&format!(
        "        public const int NameOff = {};",
        offset_of!(FmfRow, name_off)
    ));
    w(&format!(
        "        public const int ParentPathOff = {};",
        offset_of!(FmfRow, parent_path_off)
    ));
    w(&format!(
        "        public const int Flags = {};",
        offset_of!(FmfRow, flags)
    ));
    w(&format!(
        "        public const int NameLen = {};",
        offset_of!(FmfRow, name_len)
    ));
    w(&format!(
        "        public const int ParentPathLen = {};",
        offset_of!(FmfRow, parent_path_len)
    ));
    w(&format!(
        "        public const int Reserved = {};",
        offset_of!(FmfRow, _reserved)
    ));
    w("    }");
    w("");
    w(&format!(
        "    public const int EventSize = {};",
        size_of::<FmfEvent>()
    ));
    w(&format!(
        "    public const int QueryOptionsSize = {};",
        size_of::<FmfQueryOptions>()
    ));
    w(&format!(
        "    public const int VolumeStatusSize = {};",
        size_of::<FmfVolumeStatus>()
    ));
    w(&format!(
        "    public const int PageStructSize = {};",
        size_of::<FmfPage>()
    ));
    w(&format!(
        "    public const int BlobSize = {};",
        size_of::<FmfBlob>()
    ));
    w("}");
    w("");
    w("/// <summary>Result sort key carried in FmfQueryOptions.SortKey.</summary>");
    w("internal enum FmfSort : uint");
    w("{");
    for (name, value) in [
        ("Name", options::SortKey::Name as u32),
        ("Size", options::SortKey::Size as u32),
        ("Mtime", options::SortKey::Mtime as u32),
    ] {
        w(&format!("    {name} = {value},"));
    }
    w("}");
    w("");
    w("/// <summary>Case-matching mode carried in FmfQueryOptions.CaseMode.</summary>");
    w("internal enum FmfCase : uint");
    w("{");
    for (name, value) in [
        ("Smart", options::CaseMode::Smart as u32),
        ("Insensitive", options::CaseMode::Insensitive as u32),
        ("Sensitive", options::CaseMode::Sensitive as u32),
    ] {
        w(&format!("    {name} = {value},"));
    }
    w("}");
    w("");
    w("/// <summary>Whole-query regex haystack carried in regex_mode bit 1.</summary>");
    w("internal enum RegexScope : uint");
    w("{");
    for (name, value) in [
        ("Name", options::RegexScope::Name as u32),
        ("Path", options::RegexScope::Path as u32),
    ] {
        w(&format!("    {name} = {value},"));
    }
    w("}");
    w("");
    w("/// <summary>Lifecycle state carried in FmfVolumeStatus.State.</summary>");
    w("internal enum VolumeState : uint");
    w("{");
    for (name, value) in [
        ("Scanning", options::VolumeState::Scanning as u32),
        ("Ready", options::VolumeState::Ready as u32),
        ("Rescanning", options::VolumeState::Rescanning as u32),
        ("Failed", options::VolumeState::Failed as u32),
    ] {
        w(&format!("    {name} = {value},"));
    }
    w("}");
    w("");
    w("/// <summary>Event kinds — FFI FmfEvent.Kind and pipe event-push opcodes");
    w("/// carry the same values.</summary>");
    w("internal enum EventKind : uint");
    w("{");
    for (name, value) in [
        ("Progress", events::EventKind::Progress as u32),
        ("VolumeReady", events::EventKind::VolumeReady as u32),
        ("IndexChanged", events::EventKind::IndexChanged as u32),
        ("RescanStarted", events::EventKind::RescanStarted as u32),
        ("VolumeFailed", events::EventKind::VolumeFailed as u32),
        ("EngineError", events::EventKind::EngineError as u32),
    ] {
        w(&format!("    {name} = {value},"));
    }
    w("}");
    w("");
    w("/// <summary>Severity carried in FmfEvent.Entries for EngineError.</summary>");
    w("internal enum EngineErrorSeverity : ulong");
    w("{");
    for (name, value) in [
        ("Warn", events::SEVERITY_WARN),
        ("Error", events::SEVERITY_ERROR),
        ("Panic", events::SEVERITY_PANIC),
    ] {
        w(&format!("    {name} = {value},"));
    }
    w("}");
    w("");
    w("/// <summary>Degradation counters of the stats JSON (snake_case keys —");
    w("/// deserialize with SnakeCaseLower). Generated from the contract's");
    w("/// counter-name registry; nonzero values surface in the F12 panel.</summary>");
    // WinUI x:Bind reaches this type through public EngineStatsData and the
    // public DiagFormat methods. The XAML compiler requires the full property
    // type chain to be public even though this is not a supported product API.
    w("public sealed class CountersData");
    w("{");
    for name in counters::COUNTER_NAMES {
        w(&format!(
            "    public ulong {} {{ get; set; }}",
            pascal(name)
        ));
    }
    w("}");
    w("");
    w("// ── Native PODs (LayoutKind.Explicit: offsets are the Rust offset_of!");
    w("// values; Size pins the total) — the structs NativeEngine marshals. ──");
    w("internal static partial class NativeEngine");
    w("{");
    {
        let s = size_of::<FmfQueryOptions>();
        w(&format!(
            "    [StructLayout(LayoutKind.Explicit, Size = {s})]"
        ));
        w("    internal struct FmfQueryOptions");
        w("    {");
        w(&format!(
            "        [FieldOffset({})] public uint Sort;",
            offset_of!(FmfQueryOptions, sort)
        ));
        w(&format!(
            "        [FieldOffset({})] public uint Desc;",
            offset_of!(FmfQueryOptions, desc)
        ));
        w(&format!(
            "        [FieldOffset({})] public uint CaseMode;",
            offset_of!(FmfQueryOptions, case_mode)
        ));
        w(&format!(
            "        [FieldOffset({})] public uint IncludeHiddenSystem;",
            offset_of!(FmfQueryOptions, include_hidden_system)
        ));
        w(&format!(
            "        [FieldOffset({})] public uint RegexMode;",
            offset_of!(FmfQueryOptions, regex_mode)
        ));
        w(&format!(
            "        [FieldOffset({})] public uint Reserved;",
            offset_of!(FmfQueryOptions, _reserved)
        ));
        w(&format!(
            "        [FieldOffset({})] public ulong PresentationBasis;",
            offset_of!(FmfQueryOptions, presentation_basis)
        ));
        w("    }");
    }
    w("");
    {
        let s = size_of::<FmfRow>();
        w(&format!(
            "    [StructLayout(LayoutKind.Explicit, Size = {s})]"
        ));
        w("    internal struct FmfRow");
        w("    {");
        w(&format!(
            "        [FieldOffset({})] public ulong EntryRef;",
            offset_of!(FmfRow, entry_ref)
        ));
        w(&format!(
            "        [FieldOffset({})] public ulong Frn;",
            offset_of!(FmfRow, frn)
        ));
        w(&format!(
            "        [FieldOffset({})] public ulong Size;",
            offset_of!(FmfRow, size)
        ));
        w(&format!(
            "        [FieldOffset({})] public long Mtime;",
            offset_of!(FmfRow, mtime)
        ));
        w(&format!(
            "        [FieldOffset({})] public uint NameOff;",
            offset_of!(FmfRow, name_off)
        ));
        w(&format!(
            "        [FieldOffset({})] public uint ParentPathOff;",
            offset_of!(FmfRow, parent_path_off)
        ));
        w(&format!(
            "        [FieldOffset({})] public uint Flags;",
            offset_of!(FmfRow, flags)
        ));
        w(&format!(
            "        [FieldOffset({})] public uint NameLen;",
            offset_of!(FmfRow, name_len)
        ));
        w(&format!(
            "        [FieldOffset({})] public uint ParentPathLen;",
            offset_of!(FmfRow, parent_path_len)
        ));
        w(&format!(
            "        [FieldOffset({})] public uint Reserved;",
            offset_of!(FmfRow, _reserved)
        ));
        w("    }");
    }
    w("");
    {
        let s = size_of::<FmfPage>();
        w(&format!(
            "    [StructLayout(LayoutKind.Explicit, Size = {s})]"
        ));
        w("    internal struct FmfPage");
        w("    {");
        w(&format!(
            "        [FieldOffset({})] public uint RowCount;",
            offset_of!(FmfPage, row_count)
        ));
        w(&format!(
            "        [FieldOffset({})] public IntPtr Rows;",
            offset_of!(FmfPage, rows)
        ));
        w(&format!(
            "        [FieldOffset({})] public IntPtr Blob;",
            offset_of!(FmfPage, blob)
        ));
        w(&format!(
            "        [FieldOffset({})] public uint BlobLen;",
            offset_of!(FmfPage, blob_len)
        ));
        w(&format!(
            "        [FieldOffset({})] public ulong OwnerId;",
            offset_of!(FmfPage, owner_id)
        ));
        w("    }");
    }
    w("");
    {
        let s = size_of::<FmfEvent>();
        w(&format!(
            "    [StructLayout(LayoutKind.Explicit, Size = {s})]"
        ));
        w("    internal unsafe struct FmfEvent");
        w("    {");
        w(&format!(
            "        [FieldOffset({})] public uint Kind;",
            offset_of!(FmfEvent, kind)
        ));
        w(&format!(
            "        [FieldOffset({})] public ulong Entries;",
            offset_of!(FmfEvent, entries)
        ));
        w(&format!(
            "        [FieldOffset({})] public fixed byte Volume[16];",
            offset_of!(FmfEvent, volume)
        ));
        w("    }");
    }
    w("");
    {
        let s = size_of::<FmfVolumeStatus>();
        w(&format!(
            "    [StructLayout(LayoutKind.Explicit, Size = {s})]"
        ));
        w("    internal unsafe struct FmfVolumeStatus");
        w("    {");
        w(&format!(
            "        [FieldOffset({})] public fixed byte Label[16];",
            offset_of!(FmfVolumeStatus, label)
        ));
        w(&format!(
            "        [FieldOffset({})] public uint State;",
            offset_of!(FmfVolumeStatus, state)
        ));
        w(&format!(
            "        [FieldOffset({})] public ulong Entries;",
            offset_of!(FmfVolumeStatus, entries)
        ));
        w("    }");
    }
    w("");
    {
        let s = size_of::<FmfBlob>();
        w(&format!(
            "    [StructLayout(LayoutKind.Explicit, Size = {s})]"
        ));
        w("    internal struct FmfBlob");
        w("    {");
        w(&format!(
            "        [FieldOffset({})] public IntPtr Data;",
            offset_of!(FmfBlob, data)
        ));
        w(&format!(
            "        [FieldOffset({})] public uint Len;",
            offset_of!(FmfBlob, len)
        ));
        w(&format!(
            "        [FieldOffset({})] public ulong OwnerId;",
            offset_of!(FmfBlob, owner_id)
        ));
        w("    }");
    }
    w("}");

    o
}

/// Where the generated C# contract is written (committed).
fn csharp_output_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../app/FindMyFiles/Engine/Generated/EngineContract.g.cs")
}

/// Line-ending-insensitive comparison (git autocrlf may differ per clone).
fn normalize(s: &str) -> String {
    s.replace("\r\n", "\n")
}

fn main() {
    let artifacts = [(csharp_output_path(), render(), "EngineContract.g.cs")];
    let check = std::env::args().any(|a| a == "--check");
    let mut drifted = false;
    for (path, rendered, label) in &artifacts {
        if check {
            let on_disk = std::fs::read_to_string(path).unwrap_or_default();
            if normalize(&on_disk) == normalize(rendered) {
                println!("{label} is up to date");
            } else {
                eprintln!(
                    "{label} drifted from fmf-contract — regenerate with \
                     `just contract-gen` and commit the result (ADR-0018)."
                );
                drifted = true;
            }
        } else {
            std::fs::create_dir_all(path.parent().expect("generated path has a parent"))
                .expect("create generated output directory");
            std::fs::write(path, rendered).expect("write generated file");
            println!("wrote {}", path.display());
        }
    }
    if drifted {
        std::process::exit(1);
    }
}
